rangeHeight = highest(high, rangeLookback) - lowest(low, rangeLookback);
averageDailyRange = average(dailyHigh - dailyLow, adrLookbackDays); // daily bars, prior sessions
isTightTradingRange = rangeHeight <= tightRangeFraction * averageDailyRange;

// requires trend-channel-line projection from swing pivots
channelWidth = perpendicularDistance(upperChannelLine, lowerChannelLine, rangeLookback);
averageDailyRange = average(dailyHigh - dailyLow, adrLookbackDays);
isTightSlopingChannel = channelWidth <= tightRangeFraction * averageDailyRange;

middleOverlap = min(high[1], max(high[0], high[2])) - max(low[1], min(low[0], low[2]));
middleContained = middleOverlap >= barbwireOverlapFraction * (high[1] - low[1]);
hasDoji = isDoji(open[0], high[0], low[0], close[0], dojiBodyFraction) || isDoji(open[1], high[1], low[1], close[1], dojiBodyFraction) || isDoji(open[2], high[2], low[2], close[2], dojiBodyFraction);
isBarbwire = middleContained && hasDoji;

// research: 'failed breakout attempt' needs a bar-level definition (e.g., close beyond the range extreme followed by a close back inside within K bars)
failedBreakoutCount = countFailedBreakouts(rangeLookback, direction = UP);
allowBreakoutEntry = isTightTradingRange[0] && failedBreakoutCount >= minFailedBreakouts;

barsAboveEma = countBars(close[i] > ema[i], rangeLookback);
majorityAboveEma = barsAboveEma >= majorityFraction * rangeLookback;
blockShortEntry = majorityAboveEma; // mirror: block long entry when majority is below the EMA

isSmallBar = (high[0] - low[0]) <= smallBarFraction * barbwireAvgBarRange[0];
nearTop = high[0] >= barbwireHigh[0] - nearExtremeAtr * atr(atrLookback);
enterShortNextBarOpen = isBarbwire[0] && isSmallBar && nearTop;

// requires a climax/spike detector
consecutiveSellClimaxCount = countConsecutiveClimaxes(direction = DOWN);
favorLongEntries = consecutiveSellClimaxCount >= 3;
